@php($counted=$task->items->whereNotNull('actual_quantity')->count())
<section class="sc-summary"><article><span>Count task</span><strong>{{ $task->number }}</strong><small>{{ $task->warehouse->name }}</small></article><article><span>Status</span><strong class="status-text">{{ ucfirst($task->display_status) }}</strong><small>{{ $task->submitted_at?'Submitted '.$task->submitted_at->format('d M Y H:i'):($task->last_saved_at?'Saved '.$task->last_saved_at->diffForHumans():'Not started') }}</small></article><article><span>Progress</span><strong data-progress>{{ $counted }} / {{ $task->items->count() }}</strong><div class="sc-progress"><i data-progress-bar style="width:{{ $task->items->count()?round($counted/$task->items->count()*100):0 }}%"></i></div></article><article><span>Assigned user</span><strong>{{ $task->assignee->name }}</strong><small>{{ $task->assignee->email }}</small></article></section>
<section class="sc-panel sc-task-info"><div><strong>Schedule</strong><span>{{ $task->starts_at?->format('d M Y H:i')?:'Start immediately' }} → {{ $task->due_at?->format('d M Y H:i')?:'No deadline' }}</span></div><div><strong>Scope</strong><span>{{ $task->scope==='full'?'Full catalogue':'Specific products' }} · {{ $task->items->count() }} products</span></div><div class="wide"><strong>Instructions</strong><span>{{ $task->instructions?:'No special instructions.' }}</span></div></section>
@if($task->status==='submitted')<div class="alert alert-info"><strong>Frozen result:</strong> System quantities below were captured when the Warehouse User submitted the task. Later inventory movements do not change this report.</div>@endif
<section class="sc-count-list">@foreach($task->items as $item)<article class="sc-count-row" data-count-row><div class="sc-count-product">@if($image=$item->product->media->first())<img src="{{ route('catalogue.media',[$item->product,$image]) }}" alt="">@else<span><i class="fas fa-box"></i></span>@endif<div><strong>{{ $item->product->premium_marketing_name }}</strong><small>{{ $item->product->product_code ?: 'No code' }} · Barcode {{ $item->product->qr_code ?: 'not set' }} · {{ $item->product->uom ?: 'No UoM' }}</small></div></div>@if($task->status==='submitted')<div class="sc-result"><span>System at submit<strong>{{ \App\Support\NumberDisplay::quantity($item->system_quantity_snapshot,'Not tracked') }}</strong></span><span>Actual count<strong>{{ \App\Support\NumberDisplay::quantity($item->actual_quantity) }}</strong></span><span>Variance<strong class="{{ $item->variance<0?'text-danger':($item->variance>0?'text-success':'') }}">{{ $item->variance===null?'N/A':(($item->variance>0?'+':'').\App\Support\NumberDisplay::quantity($item->variance)) }}</strong></span></div>@else<form method="post" action="{{ route('admin.stock-counts.items.save',[$task,$item]) }}" class="sc-count-form">@csrf<label>Actual count<input class="form-control" type="number" name="actual_quantity" min="0" max="999999999" step="0.001" value="{{ $item->actual_quantity }}" required @disabled(!$canCount)></label><label>Note (optional)<input class="form-control" name="note" maxlength="2000" value="{{ $item->note }}" @disabled(!$canCount)></label>@if($canCount)<button class="btn btn-outline-primary">Save</button>@endif</form>@endif @if($item->note)<p class="sc-item-note"><strong>Note:</strong> {{ $item->note }}</p>@endif</article>@endforeach</section>
@if($canCount)<form method="post" action="{{ route('admin.stock-counts.submit',$task) }}" data-confirm="Finish and submit this count? The result will be frozen and cannot be edited.">@csrf<button class="btn btn-primary btn-lg sc-submit"><i class="fas fa-check-circle"></i> Finish and submit count</button></form>@endif
@if(auth()->user()->hasAdminPermission('stock-counts.manage')&&in_array($task->status,['scheduled','in_progress']))<form method="post" action="{{ route('admin.stock-counts.cancel',$task) }}" data-confirm="Cancel this stock count task?">@csrf<button class="btn btn-outline-danger mt-3">Cancel task</button></form>@endif
@if($canCount)<script>document.querySelectorAll('.sc-count-form').forEach(form=>form.addEventListener('submit',async e=>{e.preventDefault();const b=form.querySelector('button'),old=b.textContent;b.disabled=true;b.textContent='Saving…';try{const res=await fetch(form.action,{method:'POST',headers:{'Accept':'application/json','X-Requested-With':'XMLHttpRequest'},body:new FormData(form)}),data=await res.json();if(!res.ok)throw new Error(Object.values(data.errors||{}).flat()[0]||data.message);document.querySelector('[data-progress]').textContent=data.counted+' / '+data.total;document.querySelector('[data-progress-bar]').style.width=(data.counted/data.total*100)+'%';b.textContent='Saved ✓';setTimeout(()=>b.textContent=old,1200)}catch(err){alert(err.message);b.textContent=old}finally{b.disabled=false}}));</script>@endif
@if(!$canCount && in_array($task->status,['scheduled','in_progress']) && auth()->user()->hasAdminPermission('stock-counts.view'))<script>setTimeout(()=>location.reload(),30000);</script>@endif
@endsection
